public void send(Message<? extends TN> m, TN fromNode, List<TN> dests) {
    if (dests == null || dests.isEmpty()) {
      return;
    }
    if (dests.size() == 1) {
      send(m, time + 1, fromNode, dests.get(0));
    } else {
      send(m, time + 1, fromNode, dests);
    }
  }
